export function createBagModel156(){const root=new THREE.Group(),targets=new Map();root.name='Bolsa personal de herramientas156';const fabric=new THREE.MeshStandardMaterial({name:'Tela lona bolsa herramientas156',color:'#253638',roughness:.94}),rubber=new THREE.MeshStandardMaterial({name:'Goma base bolsa156',color:'#141b1c',roughness:.88}),seam=new THREE.MeshStandardMaterial({name:'Costura tela bolsa156',color:'#b5a17f',roughness:.90}),steel=new THREE.MeshStandardMaterial({name:'Acero herramienta bolsa156',color:'#9aa8ac',metalness:.85,roughness:.35});const box=(name,x,y,z,w,h,d,m,parent=root)=>{const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.name=name;o.position.set(x,y,z);parent.add(o);return o;};box('Fondo reforzado',0,-.04,0,.34,.04,.20,rubber);for(const z of[-.095,.095])box('Pared de lona',0,.03,z,.34,.12,.014,fabric);for(const x of[-.164,.164])box('Lateral lona',x,.03,0,.015,.12,.20,fabric);for(const z of[-.105,.105]){box('Correa asa',-.09,.11,z,.012,.14,.009,rubber);box('Correa asa',.09,.11,z,.012,.14,.009,rubber);box('Empuñadura',0,.175,z,.19,.015,.012,rubber);box('Costura de borde',0,.081,z,.32,.003,.003,seam);}for(const[id,x]of[['screwdriver',-.11],['wrench',-.055],['brush',0],['meter',.065]]){const g=new THREE.Group();g.position.set(x,.07,0);root.add(g);targets.set(id,g);box('Mango '+id,0,.035,0,.021,.07,.025,id==='meter'?rubber:fabric,g);box('Acero '+id,0,.10,0,.007,.07,.008,steel,g);}targets.set('hand',root);refineSurfaceMaterials100(root);root.visible=false;return{root,targets};}
